/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (($c.util.getComponent('AKCKwd').getValue() === null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "");
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    if (!await scwin.fnValidationCheck()) {
        return false;
    }
    if (!await scwin.fnPeriodValidation()) {
        return false;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchDisclosureByCorpSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "searchdisclosurebycorp_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnPeriodValidation
 * @description fn Period Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnPeriodValidation = async function () {
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    let searchCorpName = $c.util.getComponent('AKCKwd').getValue(); if (searchCorpName === null) { searchCorpName = ''; }
    let reportNmTemp = $c.util.getComponent('ipt_reportNmTemp').getValue(); if (reportNmTemp === null) { reportNmTemp = ''; }
    if (searchCorpName === "" && ($c.util.getComponent('ipt_allRepIsuSrtCd').getValue() === null ? '' : String($c.util.getComponent('ipt_allRepIsuSrtCd').getValue())) === '' && reportNmTemp === "") {
        if ($c.date.addYear(fromDate, 1) < $c.date.addYear(toDate, 0)) {
            await $c.win.alert("기간이 1년을 넘을 경우 회사명 또는 보고서명을 입력해 주세요.");
            return false;
        } else {
            return true;
        }
    } else {
        return true;
    }
};

