/**
 * @method
 * @name getCookieComCode
 * @description get Cookie Com Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCookieComCode = async function () {
    let cookiesStr = scwin.GetCookie('krxComp');
    let totalArray;
    let newVal = "";
    let newComNm = "";
    if (cookiesStr !== null) {
        cookiesStr = cookiesStr.replace("undefined", "");
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    if (totalArray) {
        for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
            const sCookieTemp = totalArray[i].split(",");
            if (i === 0) {
                newVal = newVal + sCookieTemp[1];
            } else {
                newVal = newVal + "," + sCookieTemp[1];
            }
            newComNm = sCookieTemp[2];
        }
    } else {
        await $c.win.alert("최근 검색한 회사가 없습니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", newVal);
    await scwin.fnSearch();
};

/**
 * @method
 * @name GetCookie
 * @description Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.GetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name fnBookmark
 * @description fn Bookmark 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnBookmark = function () {
    const cookieName = "krxComp";
    const cookies = scwin.GetCookie(cookieName);
    if (cookies !== null) {
        (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).removeAll ? ($c.util.getComponent('txt_myBookmark')).removeAll() : (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).setValue ? ($c.util.getComponent('txt_myBookmark')).setValue('') : void 0));
        const items = cookies.split("/");
        let max = 0;
        for (i in items) {
            if (max === 10) {
                break;
            }
            const item = items[i].split(",");
            const repIsuSrtCd = item[1];
            const corpName = item[2];
            const isurcd = item[3];
            if (undefined !== corpName && undefined !== isurcd) {
                if (corpName.indexOf('%') <= -1) {
                    $("#txt_myBookmark").append("<a href='#' onclick=\"fnBookmarkSearch('" + repIsuSrtCd + "','" + corpName + "'); return false;\" title=\"" + corpName + " 검색\" >" + corpName + "</a> ");
                }
            }
            max++;
        }
    }
};

async function fnBookmarkSearch(repIsuSrtCd, corpName) {
    $c.util.getComponent('AKCKwd').setValue(corpName);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repIsuSrtCd);
    await scwin.fnInit();
}
